import{_ as a,y as i,a as d,o as l,a2 as n,D as s,g as e,I as r}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Customer Account","description":"","frontmatter":{},"headers":[],"relativePath":"customer/customer-account.md","filePath":"customer/customer-account.md","lastUpdated":1789441803000}'),h={name:"customer/customer-account.md"};function g(c,t,u,p,m,f){const o=i("ImagePopup");return l(),d("div",null,[t[2]||(t[2]=n('<h1 id="customer-account" tabindex="-1">Customer Account <a class="header-anchor" href="#customer-account" aria-label="Permalink to &quot;Customer Account&quot;">​</a></h1><p>Shoppers who create an account get <strong>My Account</strong> on the storefront. There they manage their profile and addresses, follow their orders, download what they bought, and see their reviews, wishlist and requests. This page describes what customers can do there, so you know what they see when they ask for help. To look at a particular customer&#39;s account yourself, use <a href="./create-customer.html#sign-in-as-the-customer">Login as customer</a>.</p><h2 id="sign-up" tabindex="-1">Sign up <a class="header-anchor" href="#sign-up" aria-label="Permalink to &quot;Sign up&quot;">​</a></h2><p>Shoppers click <strong>Create your account</strong> on the sign-in page to open the <strong>Become User</strong> page.</p>',4)),s(o,{src:"/images/customer/sign-up.png",alt:"Become User sign-up page with the name, email, password and newsletter fields"}),t[3]||(t[3]=n('<ul><li><strong>First Name</strong>, <strong>Last Name</strong>, <strong>Email</strong> and <strong>Password</strong> are required. The password needs at least six characters, and <strong>Confirm Password</strong> must match it.</li><li><strong>Subscribe to newsletter</strong> appears while <strong>Allow NewsLetter</strong> is on in <a href="./../configure/settings.html#create-new-account-options">Customer Settings</a>.</li><li>An agreement checkbox appears while both <strong>Enable GDPR</strong> and the customer agreement are on in <a href="./../configure/gdpr.html#gdpr-agreement">GDPR</a>. Shoppers must tick it to register.</li><li>A captcha check is added while <a href="./../configure/google-captcha.html">Google Captcha</a> is on.</li><li>A button appears for each social account switched on in <a href="./../configure/settings.html#social-login">Customer Settings</a>.</li></ul><p><strong>Register</strong> creates the account in the default customer group and opens the <strong>Customer Login</strong> page. While email verification is on, the customer must open the link in the verification email before they can sign in. See <a href="./../configure/settings.html#email-verification">Customer Settings</a>.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>The <strong>Customer Login</strong> page asks for the <strong>Email</strong> and <strong>Password</strong>. <strong>Forgot Password?</strong> sends the customer a link to set a new password. A captcha check is added while <a href="./../configure/google-captcha.html">Google Captcha</a> is on.</p>',4)),s(o,{src:"/images/customer/sign-in.png",alt:"Customer Login page with the email and password fields and the social sign-in buttons"}),t[4]||(t[4]=n('<p>When signing in doesn&#39;t work, the page says why:</p><table tabindex="0"><thead><tr><th>Message</th><th>Why</th></tr></thead><tbody><tr><td><em>Please check your credentials and try again.</em></td><td>The email or password is wrong.</td></tr><tr><td><em>Your activation seeks admin approval</em></td><td>The account&#39;s <strong>Status</strong> is off. See <a href="./create-customer.html#edit-customer-details">Edit customer details</a>.</td></tr><tr><td><em>Verify your email account first.</em></td><td>The customer hasn&#39;t verified their email address. A <strong>Resend Verification Email</strong> link appears.</td></tr></tbody></table><p>After signing in, customers land on the home page or in their account, as set in <a href="./../configure/settings.html#login-options">Customer Settings</a>.</p><h2 id="the-my-account-menu" tabindex="-1">The My Account menu <a class="header-anchor" href="#the-my-account-menu" aria-label="Permalink to &quot;The My Account menu&quot;">​</a></h2><p>The <strong>My Account</strong> menu lists:</p><table tabindex="0"><thead><tr><th>Menu item</th><th>What customers do there</th></tr></thead><tbody><tr><td><strong>Profile</strong></td><td>See and edit their details, change their password, or delete their account.</td></tr><tr><td><strong>Address</strong></td><td>Manage their saved addresses.</td></tr><tr><td><strong>Orders</strong></td><td>Follow their orders, reorder, cancel and print invoices.</td></tr><tr><td><strong>Downloadable Products</strong></td><td>Download the files they bought.</td></tr><tr><td><strong>Reviews</strong></td><td>See the reviews they wrote.</td></tr><tr><td><strong>Wishlist</strong></td><td>Keep products for later. It appears while <strong>Allow Wishlist option</strong> is on in <a href="./../configure/settings.html#wishlist">Customer Settings</a>.</td></tr><tr><td><strong>GDPR Requests</strong></td><td>Download their data and ask for it to be updated or deleted. It appears while GDPR is on. See <a href="./gdpr-data-requests.html">GDPR Data Requests</a>.</td></tr><tr><td><strong>RMA</strong></td><td>Request returns. See <a href="./../orders/rma.html">Return Merchandise Authorization (RMA)</a>.</td></tr></tbody></table><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p><strong>Profile</strong> shows the customer&#39;s <strong>First Name</strong>, <strong>Last Name</strong>, <strong>Gender</strong>, <strong>Date of Birth</strong> and <strong>Email</strong>.</p>',8)),s(o,{src:"/images/customer/account-profile.png",alt:"Profile page in My Account with the account menu on the left"}),t[5]||(t[5]=e("h3",{id:"edit-the-profile",tabindex:"-1"},[r("Edit the profile "),e("a",{class:"header-anchor",href:"#edit-the-profile","aria-label":'Permalink to "Edit the profile"'},"​")],-1)),e("ol",null,[e("li",null,[t[0]||(t[0]=e("p",null,[r("Click "),e("strong",null,"Edit"),r(". The "),e("strong",null,"Edit Profile"),r(" page opens.")],-1)),s(o,{src:"/images/customer/account-profile-edit.png",alt:"Edit Profile page with the profile picture, name, email and phone fields"})]),t[1]||(t[1]=n("<li><p>Change the details: the profile picture, <strong>First Name</strong>, <strong>Last Name</strong>, <strong>Email</strong>, <strong>Phone</strong>, <strong>Gender</strong> and <strong>Date of Birth</strong>.</p></li><li><p>To change the password, enter the <strong>Current Password</strong>, the <strong>New Password</strong> and <strong>Confirm Password</strong>.</p></li><li><p>Tick or untick <strong>Subscribe to newsletter</strong>.</p></li><li><p>Click <strong>Save</strong>.</p></li>",4))]),t[6]||(t[6]=n('<p><strong>Phone</strong> and <strong>Gender</strong> are required. Customers who signed up on the storefront add them the first time they save their profile.</p><h3 id="delete-the-account" tabindex="-1">Delete the account <a class="header-anchor" href="#delete-the-account" aria-label="Permalink to &quot;Delete the account&quot;">​</a></h3><ol><li>Click <strong>Delete Profile</strong>.</li><li>Enter the account password.</li><li>Click <strong>Delete</strong>.</li></ol><p>The account is deleted and the customer is signed out. An account with an order that&#39;s still pending or processing can&#39;t be deleted: the page shows <em>Cannot delete customer account because some Order(s) are pending or processing state.</em></p><h2 id="address" tabindex="-1">Address <a class="header-anchor" href="#address" aria-label="Permalink to &quot;Address&quot;">​</a></h2><p><strong>Address</strong> lists the customer&#39;s saved addresses. The default one is marked <strong>Default Address</strong>.</p>',6)),s(o,{src:"/images/customer/account-addresses.png",alt:"Address page in My Account with a default address"}),t[7]||(t[7]=n('<p>To add an address:</p><ol><li>Click <strong>Add Address</strong>.</li><li>Fill in the <strong>Company Name</strong>, <strong>First Name</strong>, <strong>Last Name</strong>, <strong>Email</strong>, <strong>Vat ID</strong>, <strong>Street Address</strong>, <strong>Country</strong>, <strong>State</strong>, <strong>City</strong>, <strong>Post Code</strong> and <strong>Phone</strong>.</li><li>Tick <strong>Set as Default</strong> to make it the default address.</li><li>Click <strong>Save</strong>.</li></ol><p>The menu on each address (the three dots) has <strong>Edit</strong>, <strong>Delete</strong> and, on addresses that aren&#39;t the default, <strong>Set as Default</strong>. Which address fields are required, and how many street lines the form has, is set in <a href="./../configure/address.html">Address</a>.</p><h2 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h2><p><strong>Orders</strong> lists the customer&#39;s orders with the <strong>Order ID</strong>, <strong>Order Date</strong>, <strong>Total</strong> and <strong>Status</strong>. Customers can search and filter the list, and click the eye icon to open an order.</p>',5)),s(o,{src:"/images/customer/account-orders.png",alt:"Orders page in My Account with one closed order"}),t[8]||(t[8]=e("p",null,[r("The order page shows the items with their status, the totals, the shipping and billing addresses, and the shipping and payment methods. The "),e("strong",null,"Invoices"),r(", "),e("strong",null,"Shipments"),r(" and "),e("strong",null,"Refunds"),r(" tabs appear once the order has them.")],-1)),s(o,{src:"/images/customer/account-order-view.png",alt:"An order in My Account with the Reorder button and the Information, Invoices, Shipments and Refunds tabs"}),t[9]||(t[9]=n('<ul><li><strong>Reorder</strong> adds the order&#39;s products to the cart again. It appears while <strong>Shop Reorder</strong> is on in <a href="./../configure/orders-settings.html#allow-reorder">Order Settings</a> and the order&#39;s products can still be bought. Booking products are left out and have to be booked again.</li><li><strong>Cancel</strong> cancels the order after the customer confirms. It appears while some items haven&#39;t been invoiced or cancelled yet, unless the order is <strong>Closed</strong> or <strong>Fraud</strong>.</li><li><strong>Print</strong>, on an invoice in the <strong>Invoices</strong> tab, downloads the invoice as a PDF.</li><li><strong>Withdraw from Contract</strong> appears on orders from channels where EU withdrawals are on. After a withdrawal is made, the button reads <strong>View your withdrawal</strong>. See <a href="./../orders/eu-withdrawal.html">EU Withdrawal</a>.</li></ul><h2 id="downloadable-products" tabindex="-1">Downloadable Products <a class="header-anchor" href="#downloadable-products" aria-label="Permalink to &quot;Downloadable Products&quot;">​</a></h2><p><strong>Downloadable Products</strong> lists the files the customer bought, with the <strong>Order Id</strong>, <strong>Title</strong>, <strong>Date</strong>, <strong>Status</strong> and <strong>Remaining Downloads</strong>. Clicking the title of an available file downloads it.</p>',3)),s(o,{src:"/images/customer/account-downloadable-products.png",alt:"Downloadable Products page in My Account with an available download"}),t[10]||(t[10]=n('<table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>The order hasn&#39;t been invoiced yet, so the file can&#39;t be downloaded.</td></tr><tr><td><strong>Available</strong></td><td>The file can be downloaded.</td></tr><tr><td><strong>Expired</strong></td><td>The customer has used all their downloads, or the order was cancelled or refunded.</td></tr></tbody></table><p><strong>Remaining Downloads</strong> shows how many downloads are left: <strong>Download Allowed</strong> on the product&#39;s link, times the quantity bought, minus the downloads used. See <a href="./../product-types/downloadable-product.html">Downloadable Product</a>.</p><h2 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h2><p><strong>Reviews</strong> lists the reviews the customer has written, five per page, with the product&#39;s image, the title, rating, date and comment. Clicking a review opens the product. Customers see all their reviews here, but a review appears on the product page only after you approve it. See <a href="./customer-review.html">Customer Reviews</a>.</p><h2 id="wishlist" tabindex="-1">Wishlist <a class="header-anchor" href="#wishlist" aria-label="Permalink to &quot;Wishlist&quot;">​</a></h2><p><strong>Wishlist</strong> lists the products the customer saved for later. For each product, customers can choose a quantity and click <strong>Move To Cart</strong>, or click <strong>Remove</strong>. <strong>See Details</strong> shows the options chosen for a product, such as its color and size, and <strong>Delete All</strong> empties the wishlist.</p>',6)),s(o,{src:"/images/customer/account-wishlist.png",alt:"Wishlist page in My Account with two products and Move To Cart buttons"}),t[11]||(t[11]=e("p",null,[e("strong",null,"Move To Cart"),r(" appears while "),e("strong",null,"Cart Page"),r(" is on in "),e("a",{href:"./../configure/checkout.html#shopping-cart"},"Checkout"),r(".")],-1))])}const _=a(h,[["render",g]]);export{b as __pageData,_ as default};
